function managerPlan(teamId,opponentHand='우투'){const staff=officeAI(teamId).manager,style=staff.style||'분석형';const ps=state.players.filter(p=>p.teamId===teamId&&!p.draftPending&&!(p.profile?.injury?.days>0));const form=p=>{const ab=p.atBats||0,avg=ab?p.hits/ab:.25,weight=Math.min(1,ab/65);return (p.overall||50)*.45+batterForm(p,'contact')*.4+batterForm(p,'power')*.3+(avg-.25)*120*weight+(p.homeRuns||0)*.4-(playerBaseball(p).fatigue||0)*.3};const hitters=ps.filter(p=>p.position!=='P').sort((a,b)=>form(b)-form(a)||a.id-b.id).slice(0,16);const pitchers=ps.filter(p=>p.position==='P').sort((a,b)=>(b.overall||0)-(a.overall||0)||a.id-b.id).slice(0,12);const starters=pitchers.slice(0,5),bullpen=pitchers.slice(5),roles=new Map();starters.forEach(p=>roles.set(p.id,'선발'));bullpen.forEach((p,i)=>roles.set(p.id,i===0?'마무리':i<=2?'필승조':i===3?'추격조':i===4?'롱릴리프':'패전조'));const lineup=chooseBattingNine(hitters,opponentHand);return {first:[...pitchers,...hitters],chosenIds:new Set([...pitchers,...hitters].map(p=>p.id)),rotation:starters,starters,bullpen,roles,lineup,score:form,style}}
