function managerSubstitutions(club,inning,lead,r){if(inning<6||!club.batters.length)return;const staff=officeAI(club.teamId).manager,aggressive=staff.style==='공격형'||staff.style==='승부형';const bench=club.plan.first.filter(p=>p.position!=='P'&&!club.batters.some(x=>x.id===p.id)&&!club.substituted?.has(p.id));if(!bench.length)return;club.substituted=club.substituted||new Set();const maxChanges=aggressive?3:2;if(club.substitutions.length>=maxChanges)return;const candidates=club.batters.map((p,i)=>({p,i,fatigue:playerBaseball(p).fatigue||0,score:club.plan.score(p)})).sort((a,b)=>(b.fatigue-a.fatigue)*.65+(a.score-b.score)*.35);const weak=candidates[0];if(!weak)return;const next=bench.sort((a,b)=>club.plan.score(b)-club.plan.score(a))[0];const diff=club.plan.score(next)-weak.score;if(!(weak.fatigue>=68||inning>=7&&diff>6||inning>=8&&lead<0&&diff>2))return;const idx=weak.i;club.batters[idx]=next;club.substituted.add(weak.p.id);club.substitutions.push({inning,from:weak.p.id,to:next.id,reason:weak.fatigue>=68?'피로 교체':lead<0?'대타 투입':'타순 조정'});next.games=(next.games||0)+1}
function selectPitcher(club,inning,lead){const {plan}=club;const last=club.usage[club.usage.length-1];if(club.active&&club.active.id!==club.starter?.id&&last&&last.pitchCount<24&&last.er<3)return club.active;if(club.starter&&(!last||last.p.id===club.starter.id)&&inning<=7){const stamina=pitchingArsenal(club.starter).stamina,limit=Math.max(65,Math.min(112,83+(stamina-60)*.45));if(!last||last.pitchCount<limit&&inning<=7&&last.er<5)return club.starter}const role=inning>=9&&lead>0&&lead<=3?'마무리':lead>=0&&lead<=3?'필승조':lead<0&&lead>=-3?'추격조':lead<=-4||lead>=5?'패전조':'롱릴리프';const rested=p=>{const b=playerBaseball(p),gap=state.day-(Number(p.lastAppearance)||-99);return gap>=2&&b.fatigue<75};const choices=plan.bullpen.filter(p=>plan.roles.get(p.id)===role&&!club.used.has(p.id)&&rested(p));return choices[0]||plan.bullpen.find(p=>!club.used.has(p.id)&&rested(p))||plan.bullpen.find(p=>!club.used.has(p.id)&&playerBaseball(p).fatigue<90)||club.active||club.starter}
