function seasonDate(day){const start=state?.seasonStartDate||localTodayISO();const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+day-1);return d}function seasonDateLabel(day){const d=seasonDate(day);return d.getFullYear()+'년 '+(d.getMonth()+1)+'월 '+d.getDate()+'일 ('+['일','월','화','수','목','금','토'][d.getDay()]+')'}function scheduledPairs(day){const d=seasonDate(day),dow=d.getDay();if(dow===1||state.teams.every(t=>(t.wins||0)+(t.losses||0)+(t.draws||0)>=144))return [];const start=seasonDate(1),firstDow=start.getDay(),firstMondayOffset=(8-firstDow)%7,week=day-1<firstMondayOffset?0:Math.floor((day-1-firstMondayOffset)/7)+1;const series=week===0?0:week*2-1+(dow>=5?1:0);const ids=state.teams.map(t=>t.id),n=ids.length,round=series%(n-1),cycle=Math.floor(series/(n-1));const rotating=ids.slice(1);for(let k=0;k<round;k++)rotating.unshift(rotating.pop());const order=[ids[0],...rotating];return Array.from({length:n/2},(_,i)=>{const x=order[i],y=order[n-1-i],reverse=(round+i+cycle)%2===1;return reverse?[y,x]:[x,y]}).filter(([a,b])=>[a,b].every(id=>{const t=state.teams[id];return (t.wins||0)+(t.losses||0)+(t.draws||0)<144}))}

// Front office AI: all ten clubs share one persistent transaction ledger.
function officeAI(teamId){const t=state.teams[teamId];if(!t.staff)t.staff={};for(const [key,label] of [['president','구단 사장'],['gm','단장'],['manager','감독'],['pitchCoach','투수코치'],['batCoach','타격코치'],['scout','스카우트'],['trainer','트레이너'],['minorManager','2군 감독'],['minorPitchCoach','2군 투수코치'],['minorBatCoach','2군 타격코치'],['minorTrainer','2군 트레이너']]){if(!t.staff[key])t.staff[key]={name:'구단 '+label,skill:55+((teamId*13+key.length*7)%35)};const x=t.staff[key];if(!x.style)x.style=['육성형','분석형','승부형','안정형','공격형'][(teamId+key.length)%5]}return t.staff}
function clubNotice(kind,title,body,teams,players){if(!state.clubNotices)state.clubNotices=[];state.clubNotices.push({id:(state.clubNoticeSeq=(state.clubNoticeSeq||0)+1),day:state.day,year:state.year,kind,title,body,teams,players});if(state.clubNotices.length>1500)state.clubNotices.shift()}
function frontOfficeDay(){for(const t of state.teams)officeAI(t.id);const day=state.day;if(day%28===0){const rr=rng((day*7187+state.year*37)>>>0),ids=[...state.teams].sort((a,b)=>(a.wins/(a.wins+a.losses||1))-(b.wins/(b.wins+b.losses||1)));const a=ids[0],b=ids[ids.length-1];const candidates=state.players.filter(p=>p.teamId===a.id&&p.level!=='육성').sort((x,y)=>x.overall-y.overall);const give=candidates[0];const receive=state.players.filter(p=>p.teamId===b.id&&p.position===give?.position).sort((x,y)=>x.overall-y.overall)[0];if(give&&receive&&give.id!==receive.id){give.teamId=b.id;receive.teamId=a.id;clubNotice('트레이드','구단 간 1대1 트레이드 성사',a.city+' '+a.name+'은 '+receive.name+'을 영입하고 '+give.name+'을 내보냈습니다. '+b.city+' '+b.name+'은 '+give.name+'을 영입했습니다. 양 구단 단장의 전력 보강 판단에 따른 거래입니다.',[a.id,b.id],[give.id,receive.id])}}}

function officeDraft(){const today=seasonDate(state.day),draftYear=today.getFullYear()+1;if(today.getMonth()!==8||today.getDate()<15||state.lastOfficeDraftYear===draftYear)return;state.lastOfficeDraftYear=draftYear;const rr=rng((draftYear*7727)>>>0),order=[...state.teams].sort((a,b)=>(a.wins-a.losses)-(b.wins-b.losses));const picks=[],rounds=11;let nextId=Math.max(0,...state.players.map(p=>p.id))+1;for(let round=1;round<=rounds;round++){const selection=round%2===1?order:[...order].reverse();for(let i=0;i<selection.length;i++){const t=selection[i],p={id:nextId++,teamId:t.id,name:person(rr),age:ri(rr,18,22),position:rr()<.45?'P':['C','1B','2B','3B','SS','LF','CF','RF'][Math.floor(rr()*8)],overall:ri(rr,34,58),potential:ri(rr,55,96),salary:3e7,level:'육성',games:0,atBats:0,hits:0,homeRuns:0,inningsPitched:0,earnedRuns:0,draftYear:draftYear,draftRound:round,joinYear:draftYear,draftPending:true,draftPick:i+1};state.players.push(p);picks.push({round,pick:i+1,teamId:t.id,playerId:p.id,name:p.name,position:p.position})}}state.draftResults=state.draftResults||{};state.draftResults[draftYear]=picks;clubNotice('신인 드래프트',draftYear+' 신인 드래프트 종료… 10개 구단 11라운드 지명 완료',draftYear+'년 신인 드래프트에서 10개 구단이 총 '+picks.length+'명의 선수를 지명했습니다. 라운드별 전체 지명 결과와 선수 정보를 확인하세요.',state.teams.map(t=>t.id),picks.map(p=>p.playerId));state.clubNotices[state.clubNotices.length-1].year=draftYear}
function restoreLegacyDrafts(){if(!state.clubNotices)return;const years=[...new Set(state.clubNotices.filter(n=>n.kind==='신인 드래프트').map(n=>n.year))];state.draftResults=state.draftResults||{};for(const year of years){if(state.draftResults[year]?.length)continue;const notices=state.clubNotices.filter(n=>n.kind==='신인 드래프트'&&n.year===year),ids=new Set(notices.flatMap(n=>n.players||[]));const existing=state.players.filter(p=>ids.has(p.id));state.draftResults[year]=existing.map((p,i)=>({round:1,pick:i+1,teamId:p.teamId,playerId:p.id,name:p.name,position:p.position}));}}
function rosterNewsGroups(){const grouped=new Map();for(const n of state.clubNotices||[]){if(!['1군 콜업','1군 말소','부상자 명단','1군 등록'].includes(n.kind))continue;const teamId=n.teams?.[0];if(teamId==null)continue;const key=n.day+':'+teamId;if(!grouped.has(key))grouped.set(key,{day:n.day,teamId,notices:[],players:new Set()});const g=grouped.get(key);g.notices.push(n);for(const id of n.players||[])g.players.add(id)}return grouped}
