function minorLeagueDay(){for(const t of state.teams){const staff=officeAI(t.id),minor=state.players.filter(p=>p.teamId===t.id&&p.level==='2군'&&!p.draftPending&&!(p.profile?.injury?.days>0));const r=rng((state.day*13007+t.id*811+37)>>>0);for(const p of minor){p.minorStats=p.minorStats||{games:0,atBats:0,hits:0,homeRuns:0,innings:0,strikeouts:0};const m=p.minorStats;m.games++;if(p.position==='P'){m.innings+=ri(r,0,5);m.strikeouts+=ri(r,0,5)}else{const ab=ri(r,2,5);m.atBats+=ab;for(let i=0;i<ab;i++)if(r()<Math.max(.12,Math.min(.4,.24+((p.overall||55)-55)*.002)))m.hits++;if(r()<Math.max(.01,((p.overall||55)-35)*.0006))m.homeRuns++}if(m.games%20===0&&r()<((staff.minorManager.skill||65)+(staff.minorBatCoach.skill||65))/3500)p.overall=Math.min(p.potential||99,(p.overall||50)+1)}}}
function minorCoachReview(team,position){const staff=officeAI(team.id),coach=staff.minorManager,players=state.players.filter(p=>p.teamId===team.id&&p.level==='2군'&&!p.draftPending&&!(p.profile?.injury?.days>0)&&(position==='P'?p.position==='P':p.position!=='P'));return players.sort((a,b)=>{const rating=p=>(p.overall||0)+Math.min(8,(p.minorStats?.games||0)/15)+(p.position==='P'?Math.min(6,(p.minorStats?.strikeouts||0)/20):Math.min(6,(p.minorStats?.hits||0)/15));return rating(b)-rating(a)})}
function medicalRosterDay(){const day=state.day;for(const p of state.players){const b=playerBaseball(p),inj=p.profile?.injury;if(inj&&inj.days>0){inj.days--;if(inj.days===0){inj.recoveredDay=day;clubNotice('부상 복귀',p.name+' 재활 완료 · 선수단 복귀',p.name+' 선수가 재활을 마치고 출전 가능한 상태가 됐습니다.',[p.teamId],[p.id])}}if(p.position!=='P')b.fatigue=Math.max(0,(Number(b.fatigue)||0)-8)}for(const t of state.teams){const team=state.players.filter(p=>p.teamId===t.id&&!p.draftPending),active=team.filter(p=>p.level==='1군'),healthy=active.filter(p=>!(p.profile?.injury?.days>0));for(const p of active.filter(p=>p.profile?.injury?.days>0)){if(p.profile.injury.days>=5){p.level='2군';p.injuryDemoted=true;clubNotice('부상자 명단',t.name+' '+p.name+' 부상으로 1군 말소',p.name+' 선수가 '+p.profile.injury.type+' 부상으로 '+p.profile.injury.days+'일간 재활에 들어갑니다.',[t.id],[p.id])}}const now=team.filter(p=>p.level==='1군'&&!(p.profile?.injury?.days>0));const desiredPitchers=12,desiredBatters=16;for(const position of ['P','B']){const count=now.filter(p=>position==='P'?p.position==='P':p.position!=='P').length,target=position==='P'?desiredPitchers:desiredBatters;if(count>=target)continue;const candidates=minorCoachReview(t,position);for(const p of candidates.slice(0,target-count)){p.level='1군';now.push(p);clubNotice('1군 콜업',t.name+' '+p.name+' 1군 등록',t.name+' 2군 감독의 추천과 1군 감독의 판단으로 '+p.name+' 선수를 1군에 등록했습니다.',[t.id],[p.id])}}}}
function gameInjuryCheck(club,inning,r){if(!club.batters.length)return;const p=club.batters[Math.floor(r()*club.batters.length)];if(!p||p.profile?.injury?.days>0||r()>.0012)return;const types=['허벅지 근육','발목','손목','어깨','허리'],type=types[Math.floor(r()*types.length)],days=ri(r,3,28);ensureProfile(p).injury={type,days,occurredDay:state.day};const bench=club.plan.first.filter(x=>x.position!=='P'&&!club.batters.some(y=>y.id===x.id)&&!(x.profile?.injury?.days>0));const idx=club.batters.findIndex(x=>x.id===p.id);if(bench.length&&idx>=0){const sub=bench.sort((a,b)=>club.plan.score(b)-club.plan.score(a))[0];club.batters[idx]=sub;club.substitutions.push({inning,from:p.id,to:sub.id,reason:'부상 교체'});sub.games=(sub.games||0)+1}club.injuries.push({playerId:p.id,type,days});clubNotice('선수 부상',state.teams[club.teamId].name+' '+p.name+' 경기 중 부상',p.name+' 선수가 '+inning+'회 경기 중 '+type+' 부상을 입었습니다. 예상 회복 기간은 '+days+'일입니다.',[club.teamId],[p.id])}
function simulateLeagueDay(){activateDraftRookies();minorLeagueDay();medicalRosterDay();officeDraft();frontOfficeDay();ensureSeasonCalendar();if(!state.gameResults)state.gameResults=[];for(const p of state.players){if(p.position!=='P')continue;const b=playerBaseball(p);b.fatigue=Math.max(0,(Number(b.fatigue)||0)-(Number(b.recovery)||10));const a=pitchingArsenal(p);if(p.age<=31&&a.pitches.length<5){const rr=rng((p.id*1031+state.day*7919)>>>0);if(rr()<.0007*(p.potential>=75?2:1)){const extra=PITCH_TYPES.filter(x=>!a.pitches.some(y=>y.name===x));if(extra.length){const name=extra[Math.floor(rr()*extra.length)];a.pitches.push({name,grade:Math.max(25,Math.min(85,p.overall+ri(rr,-24,4)))});a.usage=null}}}}const day=state.day,r=rng(((state.year||2027)*100003+day*7919)>>>0),pairs=scheduledPairs(day);for(const [a,b] of pairs){const away=inningClub(a,day,'우투'),home=inningClub(b,day,'우투');const beforeBat=new Map(state.players.filter(p=>p.teamId===a||p.teamId===b).map(p=>[p.id,Object.fromEntries(['atBats','hits','homeRuns','runsBattedIn','runs','walks','stolenBases'].map(k=>[k,p[k]||0]))]));for(const p of [...away.batters,...home.batters])p.games=(p.games||0)+1;for(let inning=1;inning<=12;inning++){gameInjuryCheck(away,inning,r);managerSubstitutions(away,inning,home.runs-away.runs,r);const preAway=away.runs,preHome=home.runs;home.opponentRuns=away.runs;const ar=playHalf(away,home,inning,r);away.innings.push(ar);if(inning>=9&&home.runs>away.runs){home.innings.push(null);break}gameInjuryCheck(home,inning,r);managerSubstitutions(home,inning,away.runs-home.runs,r);const preHomeBat=home.runs;away.opponentRuns=home.runs;const hr=playHalf(home,away,inning,r);home.innings.push(hr);if(inning>=9&&home.runs!==away.runs)break}if(away.runs===home.runs){state.teams[a].draws=(state.teams[a].draws||0)+1;state.teams[b].draws=(state.teams[b].draws||0)+1}else{const win=away.runs>home.runs?a:b,lose=win===a?b:a;state.teams[win].wins++;state.teams[lose].losses++}finishPitchers(away,away.runs>home.runs,home.runs);finishPitchers(home,home.runs>away.runs,away.runs);for(const c of [away,home]){const records=c.pitcherUsage||[];const winnerRecords=records.filter(x=>x.win),loserRecords=records.filter(x=>x.loss),saves=records.filter(x=>x.save);if(winnerRecords.length>1||loserRecords.length>1||saves.length>1||records.some(x=>x.win&&(x.save||x.hold)||x.loss&&(x.save||x.hold)||x.save&&x.hold)){console.warn('투수 공식기록 검증 실패',state.day,c.teamId,records.map(x=>({id:x.id,win:x.win,loss:x.loss,save:x.save,hold:x.hold})))}}const gameBatters=c=>[...new Map([...c.batters,...c.substitutions.map(x=>state.players.find(p=>p.id===x.from)).filter(Boolean)].map(p=>[p.id,p])).values()].map(p=>{const old=beforeBat.get(p.id)||{};return {id:p.id,name:p.name,...Object.fromEntries(['atBats','hits','homeRuns','runsBattedIn','runs','walks','stolenBases'].map(k=>[k,(p[k]||0)-(old[k]||0)]))}});const result={awayErrors:away.errors||0,homeErrors:home.errors||0,day,venue:stadiumFactors(b).name,parkType:stadiumFactors(b).type,date:seasonDateLabel(day),awayBatters:gameBatters(away),homeBatters:gameBatters(home),away:a,home:b,awayRuns:away.runs,homeRuns:home.runs,awayInnings:away.innings,homeInnings:home.innings,awayPitchers:away.pitcherUsage,homePitchers:home.pitcherUsage,awaySubstitutions:away.substitutions,homeSubstitutions:home.substitutions,awayInjuries:away.injuries,homeInjuries:home.injuries};state.gameResults.push(result);if(a===state.teamId||b===state.teamId)state.events.push({day,title:'정규시즌 경기 결과',body:state.teams[a].city+' '+state.teams[a].name+' '+away.runs+' : '+home.runs+' '+state.teams[b].city+' '+state.teams[b].name})}state.day++;finalizeAwards();if(state.events.length>150)state.events=state.events.slice(-150)}
async function advanceSeason(){const btn=document.querySelector('#advance-day');if(btn)btn.disabled=true;const backup=structuredClone(state);try{ensureSeasonCalendar();simulateLeagueDay();const latest=(state.gameResults||[]).at(-1);if(latest)window.beNewsDay=latest.day;await save()}catch(e){state=backup;render();alert('경기 진행 및 저장 실패: '+e.message)}}

function newsStory(g){const a=state.teams[g.away],h=state.teams[g.home],draw=g.awayRuns===g.homeRuns,awayWin=g.awayRuns>g.homeRuns,w=awayWin?a:h,l=awayWin?h:a,margin=Math.abs(g.awayRuns-g.homeRuns),ai=g.awayInnings||[],hi=g.homeInnings||[];let ar=0,hr=0,decisive=null,peak=null,turns=[];for(let i=0;i<Math.max(ai.length,hi.length);i++){const x=Number(ai[i])||0,y=Number(hi[i])||0,previous=ar-hr;ar+=x;hr+=y;if(x+y){turns.push({inning:i+1,away:x,home:y,scoreA:ar,scoreH:hr});if(!peak||x+y>peak.away+peak.home)peak=turns[turns.length-1];if(previous!==0&&Math.sign(previous)!==Math.sign(ar-hr)&&ar!==hr)decisive=turns[turns.length-1]}}const title=draw?esc(a.name)+'·'+esc(h.name)+', 연장 끝 무승부':margin>=7?esc(w.name)+', '+margin+'점 차 압승…'+esc(l.name)+' 제압':margin===1?esc(w.name)+', '+esc(l.name)+'에 한 점 차 승리':esc(w.name)+', '+esc(l.name)+' 꺾고 '+margin+'점 차 승리';const summary=draw?esc(a.city+' '+a.name)+'와 '+esc(h.city+' '+h.name)+'가 '+g.awayRuns+'대 '+g.homeRuns+'로 승부를 가리지 못했다.':esc(w.city+' '+w.name)+'가 '+esc(l.city+' '+l.name)+'를 '+Math.max(g.awayRuns,g.homeRuns)+'대 '+Math.min(g.awayRuns,g.homeRuns)+'로 꺾었다.';return {title,summary,turns,decisive,peak,draw,margin}}
function gameArticle(g){const a=state.teams[g.away],h=state.teams[g.home],story=newsStory(g),ai=Array.isArray(g.awayInnings)?g.awayInnings:[],hi=Array.isArray(g.homeInnings)?g.homeInnings:[],n=Math.max(9,ai.length,hi.length),innings=Array.from({length:n},(_,i)=>i+1),winner=g.awayRuns>g.homeRuns?a:h,loser=winner===a?h:a;const row=(name,values,total)=>'<tr><th>'+esc(name)+'</th>'+innings.map((_,i)=>'<td>'+(values[i]===null?'-':values[i]??'-')+'</td>').join('')+'<td><b>'+total+'</b></td></tr>';const scored=story.turns||[],first=scored[0],peak=story.peak,decisive=story.decisive;const lead=story.draw?'승부는 마지막까지 팽팽했다. 두 팀은 '+g.awayRuns+'대 '+g.homeRuns+'로 경기를 마쳤다.':esc(winner.city+' '+winner.name)+'가 '+esc(loser.city+' '+loser.name)+'를 상대로 '+Math.max(g.awayRuns,g.homeRuns)+'대 '+Math.min(g.awayRuns,g.homeRuns)+' 승리를 거뒀다. '+(story.margin>=5?'큰 점수 차를 만들어낸 공격력이 승부를 갈랐다.':story.margin===1?'끝까지 승부를 알 수 없는 한 점 차 접전이었다.':'득점 기회를 살린 쪽이 승리를 가져갔다.');const paragraph1=first?'경기 초반부터 점수판이 움직였다. '+first.inning+'회 '+(first.away?esc(a.name)+'가 '+first.away+'점을 올렸고 ':'')+(first.home?esc(h.name)+'도 '+first.home+'점을 보탰다. ':'')+'이 이닝을 마친 시점 점수는 '+first.scoreA+'대 '+first.scoreH+'였다.':'경기 내내 양 팀은 득점을 올리지 못했다.';const paragraph2=decisive?'승부의 흐름이 달라진 시점은 '+decisive.inning+'회였다. 이 이닝에 '+(decisive.away?esc(a.name)+'가 '+decisive.away+'점을 기록했고 ':'')+(decisive.home?esc(h.name)+'가 '+decisive.home+'점을 추가하면서 ':'')+'누적 점수가 '+decisive.scoreA+'대 '+decisive.scoreH+'로 바뀌었다.':peak?'특히 '+peak.inning+'회에는 두 팀이 합쳐 '+(peak.away+peak.home)+'점을 올렸다. '+(peak.away?esc(a.name)+'의 '+peak.away+'득점':'')+(peak.away&&peak.home?'과 ':'')+(peak.home?esc(h.name)+'의 '+peak.home+'득점':'')+'이 집중된 이닝이었다.':'양 팀은 끝까지 팽팽한 투수전을 이어갔다.';const last=scored[scored.length-1],paragraph3=last&&last!==first?'이후에도 공방이 이어졌다. '+last.inning+'회에는 '+(last.away?esc(a.name)+'가 '+last.away+'점 ':'')+(last.home?esc(h.name)+'가 '+last.home+'점':'')+'을 올렸고, 최종 스코어는 '+g.awayRuns+'대 '+g.homeRuns+'로 확정됐다.':'경기 종료 후 전광판에는 '+g.awayRuns+'대 '+g.homeRuns+'가 남았다.';const pitchers=(id,records)=>'<div class="article-pitcher-team"><h5>'+esc(state.teams[id].city+' '+state.teams[id].name)+'</h5><ul>'+((records||[]).slice().sort((a,b)=>(a.entry??(a.role==='선발'?1:99))-(b.entry??(b.role==='선발'?1:99))).map(x=>{const p=state.players.find(p=>p.id===x.id);return p?'<li><button class="article-player-link" data-article-player="'+p.id+'">'+esc(p.name)+'</button><span>'+esc(x.role||'투수')+(x.role==='선발'?'':x.entry!=null?' · '+x.entry+'회 등판':'')+' · '+baseballIP(x.outs!=null?x.outs:Math.round((x.innings||0)*3))+'이닝 · '+(x.strikeouts??'—')+'K · '+(x.hits??'—')+'피안타 · '+(x.walks??'—')+'볼넷 · '+(x.earnedRuns??'—')+'자책'+(x.win?' · 승리':x.loss?' · 패전':x.save?' · 세이브':'')+'</span></li>':''}).filter(Boolean).join('')||'<li>기록 없음</li>')+'</ul></div>';const battingBox=(id,ps)=>!Array.isArray(ps)?'<p class="article-note">이 경기는 타자별 기록이 저장되지 않았습니다.</p>':'<h5>'+esc(state.teams[id].city+' '+state.teams[id].name)+'</h5><div class="scoreboard-scroll"><table class="scoreboard-table"><thead><tr><th>선수</th><th>타수</th><th>안타</th><th>홈런</th><th>타점</th><th>득점</th><th>볼넷</th><th>도루</th></tr></thead><tbody>'+ps.map(p=>'<tr><th><button class="article-player-link" data-article-player="'+p.id+'">'+esc(p.name)+'</button></th><td>'+p.atBats+'</td><td>'+p.hits+'</td><td>'+p.homeRuns+'</td><td>'+p.runsBattedIn+'</td><td>'+(p.runs??'—')+'</td><td>'+p.walks+'</td><td>'+p.stolenBases+'</td></tr>').join('')+'</tbody></table></div>';const topBatters=[...(g.awayBatters||[]),...(g.homeBatters||[])].filter(p=>p.runsBattedIn||p.homeRuns).sort((a,b)=>b.runsBattedIn-a.runsBattedIn||b.homeRuns-a.homeRuns).slice(0,4);const highlights=[...(g.awayBatters||[]).map(x=>({...x,club:g.away})),...(g.homeBatters||[]).map(x=>({...x,club:g.home}))].filter(x=>x.homeRuns||x.runsBattedIn>=2||x.hits>=3).sort((a,b)=>b.homeRuns-a.homeRuns||b.runsBattedIn-a.runsBattedIn).slice(0,4);const hitterStory=highlights.map(x=>{const lost=x.club===g.away?g.awayRuns<g.homeRuns:g.homeRuns<g.awayRuns;return esc(state.teams[x.club].name+' '+x.name)+'은 '+(x.homeRuns?x.homeRuns+'홈런 ':'')+x.hits+'안타 '+x.runsBattedIn+'타점을 기록했다.'+(lost&&x.homeRuns?' 홈런을 쳤지만 팀은 패했다.':'')}).join(' ');const starterStory=[{club:g.away,ps:g.awayPitchers||[]},{club:g.home,ps:g.homePitchers||[]}].map(t=>{const x=t.ps.find(p=>p.role==='선발')||t.ps[0],p=x&&state.players.find(p=>p.id===x.id);if(!p)return '';const outs=Number.isInteger(x.outs)?x.outs:Math.round((x.innings||0)*3);return esc(state.teams[t.club].name+' 선발 '+p.name)+'은 '+Math.floor(outs/3)+'과 '+outs%3+'/3이닝 '+(x.earnedRuns??'—')+'자책'+(x.strikeouts!=null?' '+x.strikeouts+'탈삼진':'')+(x.hits!=null?' '+x.hits+'피안타':'')+'를 기록했다.'}).filter(Boolean).join(' ');const playerStory='<p>'+hitterStory+'</p>'+(starterStory?'<p>'+starterStory+'</p>':'');return '<div class="news-article-body editorial-story"><div class="article-category">스포츠 <span>›</span> 야구 <span>›</span> 정규시즌</div><h1 class="editorial-headline">'+story.title+'</h1><p class="editorial-subtitle">'+lead+'</p><div class="editorial-meta"><strong>BASEBALL EMPIRE 스포츠팀</strong><span>'+seasonDateLabel(g.day)+' | 경기 종료</span></div><div class="editorial-hero"><div class="editorial-stadium"><div class="editorial-winner-logo">'+teamLogo(winner,true)+'<span>WINNER · '+esc(winner.city+' '+winner.name)+'</span></div><div class="editorial-hero-title">'+esc(a.name)+' <b>'+g.awayRuns+' : '+g.homeRuns+'</b> '+esc(h.name)+'</div></div><div class="editorial-caption">BASEBALL EMPIRE 경기 결과 · 게임 내 자동 생성된 그래픽</div></div><div class="editorial-copy"><p>'+lead+'</p><p>'+paragraph1+'</p><p>'+paragraph2+'</p><p>'+paragraph3+'</p>'+playerStory+'</div><div class="editorial-points"><h3>주요 포인트</h3><ul><li>최종 결과: '+esc(a.name)+' '+g.awayRuns+'대 '+g.homeRuns+' '+esc(h.name)+'</li>'+(peak?'<li>최다 득점 이닝: '+peak.inning+'회, 양 팀 합계 '+(peak.away+peak.home)+'점</li>':'')+(decisive?'<li>경기 흐름 변화: '+decisive.inning+'회, 누적 '+decisive.scoreA+'대 '+decisive.scoreH+'</li>':'')+'<li>경기장: '+esc(typeof g.venue==='string'&&g.venue.trim()&&!/^\\d+$/.test(g.venue.trim())?g.venue:ballpark(state.teams[g.home]))+' · '+esc(g.parkType||stadiumFactors(g.home).type)+'</li><li>경기 결과와 선수 기록은 저장된 시뮬레이션 데이터 기준</li></ul></div><h4>이닝별 점수</h4><div class="scoreboard-scroll"><table class="scoreboard-table"><thead><tr><th>구단</th>'+innings.map(i=>'<th>'+i+'</th>').join('')+'<th>R</th></tr></thead><tbody>'+row(a.name,ai,g.awayRuns)+row(h.name,hi,g.homeRuns)+'</tbody></table></div><h4>양 팀 타자 기록</h4>'+battingBox(g.away,g.awayBatters)+battingBox(g.home,g.homeBatters)+'<h4>투수 주요 기록</h4><div class="article-pitchers">'+pitchers(g.away,g.awayPitchers)+pitchers(g.home,g.homePitchers)+'</div><p class="article-note">본 기사는 게임 내 실제 경기 결과를 바탕으로 자동 작성됐습니다.</p></div>'}
function displayedGameDay(){const all=state.gameResults||[];return all.length?Math.max(...all.map(g=>g.day)):state.day}
function recentScoreboards(){const all=state.gameResults||[],days=[...new Set(all.map(g=>g.day))].sort((a,b)=>b-a),day=days.includes(window.beNewsDay)?window.beNewsDay:days[0];if(day===undefined)return '<p class="roster-empty">아직 진행된 경기가 없습니다.</p>';const games=all.filter(g=>g.day===day).sort((a,b)=>(a.away===state.teamId||a.home===state.teamId?-1:0)-(b.away===state.teamId||b.home===state.teamId?-1:0));return '<div class="news-day-picker"><button type="button" id="news-prev-day" '+(days.indexOf(day)===days.length-1?'disabled':'')+'>‹ 이전 경기일</button><strong>'+seasonDateLabel(day)+' · '+games.length+'경기</strong><button type="button" id="news-next-day" '+(days.indexOf(day)===0?'disabled':'')+'>다음 경기일 ›</button></div><div class="news-headlines">'+games.map((g,i)=>'<button class="news-headline" data-game-day="'+g.day+'" data-game-away="'+g.away+'"><span class="news-headline-day">'+(g.away===state.teamId||g.home===state.teamId?'우리 팀':'리그')+'</span><strong>'+newsStory(g).title+'</strong><span class="news-headline-arrow">›</span></button>').join('')+'</div>'}
function openGameArticle(day,away){const g=(state.gameResults||[]).find(g=>g.day===day&&g.away===away);if(!g)return;document.querySelector('#game-news-overlay')?.remove();document.body.insertAdjacentHTML('beforeend','<div id="game-news-overlay" class="game-news-overlay"><article class="game-news-dialog" role="dialog" aria-modal="true" aria-label="경기 상세 기사"><header><div><small>BASEBALL EMPIRE SPORTS · '+seasonDateLabel(g.day)+'</small><h2>'+newsStory(g).title+'</h2></div><button id="close-game-news" type="button">× 닫기</button></header>'+gameArticle(g)+'</article></div>');document.querySelector('#close-game-news').onclick=closeGameArticle;document.querySelector('#game-news-overlay').onclick=e=>{if(e.target.id==='game-news-overlay')closeGameArticle()};document.addEventListener('keydown',gameNewsEscape);document.querySelectorAll('[data-article-player]').forEach(x=>x.onclick=()=>showPlayer(Number(x.dataset.articlePlayer)))}
