function closeGameArticle(){document.querySelector('#game-news-overlay')?.remove();document.removeEventListener('keydown',gameNewsEscape)}
function nextSchedulePanel(){const day=state.day,date=seasonDateLabel(day),pairs=scheduledPairs(day),mine=pairs.find(([a,b])=>a===state.teamId||b===state.teamId);if(!mine)return '<div class="next-schedule"><strong>다음 날 · '+date+'</strong><div class="schedule-match">월요일 휴식일 · 우리 팀 경기 없음</div></div>';const [a,b]=mine,away=state.teams[a],home=state.teams[b],isHome=b===state.teamId;return '<div class="next-schedule"><strong>다음 날 우리 팀 경기 · '+date+'</strong><div class="schedule-match"><b>'+(isHome?'홈 경기':'원정 경기')+'</b> · '+esc(isHome?away.city+' '+away.name:home.city+' '+home.name)+' 상대</div><div class="schedule-match">경기 장소 · '+esc(ballpark(home))+'</div></div>'}
function home(){const t=state.teams[state.teamId],rank=[...state.teams].sort((a,b)=>b.wins-a.wins).findIndex(x=>x.id===t.id)+1,ps=state.players.filter(p=>p.teamId===t.id);const tiles=[['리그 순위',rank+'위','전체 10개 구단'],['시즌 성적',t.wins+'승 '+t.losses+'패','2027 정규시즌'],['구단 자금',money(t.budget),'구단 재정'],['팬 규모',t.fans.toLocaleString()+'명','구단 팬 기반']];return '<section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">AUTO SEASON</span><h2>'+seasonDateLabel(displayedGameDay())+' · 정규시즌</h2></div></div>'+nextSchedulePanel()+'<button id="advance-day">하루 진행</button></section><section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">GAME RESULTS</span><h2>최근 경기 · 스포츠 뉴스</h2></div></div>'+recentScoreboards()+'</section><section class="dashboard-intro"><span class="section-kicker">CLUB OVERVIEW</span><h2>구단 현황</h2><p>구단의 시즌 운영 상황을 한눈에 확인하세요.</p></section><div class="overview-grid">'+tiles.map((x,i)=>'<article class="overview-tile"><div class="overview-icon">'+['◆','▣','₩','♡'][i]+'</div><div class="overview-label">'+x[0]+'</div><strong>'+x[1]+'</strong><small>'+x[2]+'</small></article>').join('')+'</div><section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">FRONT OFFICE</span><h2>구단 운영진</h2></div></div><div class="staff-list">'+[['사장',t.staff.president],['단장',t.staff.gm],['감독',t.staff.manager]].map(x=>'<div class="staff-person"><span class="staff-avatar">'+esc(x[1].name.slice(0,1))+'</span><div><small>'+x[0]+'</small><strong>'+esc(x[1].name)+'</strong></div><span class="staff-status">재직 중</span></div>').join('')+'</div></section><section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">CLUB NEWS</span><h2>구단 소식</h2></div></div><div class="news-list">'+state.events.filter(e=>e.title!=='정규시즌 경기 결과').slice(-5).reverse().map(e=>'<article class="news-item"><span class="news-dot"></span><div><strong>'+esc(e.title)+'</strong><p>'+esc(e.body)+'</p></div></article>').join('')+'</div></section>'+clubNewsPanel()+'<section class="dashboard-section save-section"><div class="section-title"><div><span class="section-kicker">SAVE & BACKUP</span><h2>게임 데이터</h2></div></div><p class="save-date">마지막 저장 · '+(state.lastSaved?new Date(state.lastSaved).toLocaleString('ko-KR'):'기록 없음')+'</p><div class="save-actions"><button id="save">지금 저장</button><button id="backup" class="secondary">백업 다운로드</button><label class="restore-label">백업 파일 불러오기 <input id="restore" type="file" accept="application/json,.json"></label></div></section>'}
function batterSkill(p,key){const o=Number(p.overall)||50,offset=((p.id*131+(key==='speed'?17:key==='power'?41:67))%31)-15;return Math.max(20,Math.min(99,o+offset))}
function batterForm(p,key){const ab=Number(p.atBats)||0,prior=batterSkill(p,key),weight=Math.min(.65,ab/(ab+140));if(!ab)return prior;let observed=prior;if(key==='contact')observed=Math.min(99,Math.max(20,50+((Number(p.hits)||0)/ab-.255)*170));if(key==='power')observed=Math.min(99,Math.max(20,45+((Number(p.homeRuns)||0)/ab-.035)*520));if(key==='speed')observed=Math.min(99,Math.max(20,45+((Number(p.stolenBases)||0)/Math.max(1,Number(p.games)||1)-.12)*100));return prior*(1-weight)+observed*weight}
function battingOrder(players){const remaining=[...players],weights=[['contact',1.25,'speed',1.15,'power',.2],['contact',1.3,'speed',.8,'power',.4],['contact',1.2,'power',1.2,'speed',.25],['power',2,'contact',.55,'speed',0],['power',1.65,'contact',.7,'speed',.15],['power',1.2,'contact',.8,'speed',.2],['contact',.85,'power',.65,'speed',.35],['contact',.8,'speed',.6,'power',.25],['speed',1.15,'contact',.85,'power',.15]];return weights.map(w=>{const rating=p=>batterForm(p,w[0])*w[1]+batterForm(p,w[2])*w[3]+batterForm(p,w[4])*w[5];remaining.sort((a,b)=>rating(b)-rating(a)||a.id-b.id);return remaining.shift()}).filter(Boolean)}
function defensiveFit(p,slot){if(p.position===slot)return 22;if(p.position==='IF'&&['1B','2B','3B','SS'].includes(slot))return 12;if(p.position==='OF'&&['LF','CF','RF'].includes(slot))return 12;if(['LF','CF','RF'].includes(p.position)&&['LF','CF','RF'].includes(slot))return 7;if(['2B','SS','3B'].includes(p.position)&&['2B','SS','3B'].includes(slot))return 5;return -24}
function chooseBattingNine(players,opponentHand){const slots=['C','1B','2B','3B','SS','LF','CF','RF','DH'],pool=[...players],chosen=[];for(const slot of slots){pool.sort((a,b)=>{const val=p=>batterForm(p,'contact')*.75+batterForm(p,'power')*.65+defensiveFit(p,slot)-(Number(playerBaseball(p).fatigue)||0)*.6+(opponentHand&&playerBaseball(p).batHand===(opponentHand==='좌투'?'우타':'좌타')?4:0);return val(b)-val(a)||a.id-b.id});if(pool.length)chosen.push(pool.shift())}return battingOrder(chosen)}
function recoverClub(teamId){for(const p of state.players){if(p.teamId!==teamId)continue;const b=playerBaseball(p);b.fatigue=Math.max(0,(Number(b.fatigue)||0)-(Number(b.recovery)||10))}}
function autoManager(){return managerPlan(state.teamId)}
function lineupState(){const m=autoManager();return {batting:m.lineup.map(p=>p.id),rotation:m.rotation.map(p=>p.id)}}
function statNumber(p,keys){for(const k of keys){if(p[k]!==undefined&&p[k]!==null&&Number.isFinite(Number(p[k])))return Number(p[k]);if(p.stats&&p.stats[k]!==undefined&&p.stats[k]!==null&&Number.isFinite(Number(p.stats[k])))return Number(p.stats[k])}return null}
function baseballStatLine(p,role){const get=(...keys)=>statNumber(p,keys),fmt=n=>n===null?'—':String(n),ip=get('inningsPitched'),er=get('earnedRuns'),h=get('hitsAllowed'),bb=get('walksAllowed','basesOnBallsAllowed'),era=ip>0&&er!==null?(er*9/ip).toFixed(2):'—',whip=ip>0&&h!==null&&bb!==null?((h+bb)/ip).toFixed(2):'—',w=fmt(get('pitchingWins','pitcherWins','win')??0),l=fmt(get('pitchingLosses','pitcherLosses','loss')??0),k=fmt(get('pitchingStrikeouts','strikeoutsPitched','strikeouts'));if(p.position==='P'){if(role==='선발'||role==='선발투수')return [['평균자책점',era],['승패',w+'-'+l],['IP',ip===null?'—':baseballIP(Math.round(ip*3))],['탈삼진',k],['이닝당 출루 허용',whip],['QS',fmt(get('qualityStarts','qs'))]];return [['평균자책점',era],['G',fmt(get('games'))],['승패',w+'-'+l],['홀드',fmt(get('holds','hold'))],['세이브',fmt(get('saves','save'))],['블론세이브',fmt(get('blownSaves','blownSave'))],['이닝당 출루 허용',whip],['탈삼진',k]]}const ab=get('atBats'),hits=get('hits'),hr=get('homeRuns'),doubles=get('doubles','twoBaseHits'),triples=get('triples','threeBaseHits'),walks=get('walks','basesOnBalls'),hbp=get('hitByPitch','hitByPitches'),sf=get('sacrificeFlies');const avg=ab>0&&hits!==null?(hits/ab).toFixed(3).replace(/^0/,''):'—';const obp=ab!==null&&hits!==null&&walks!==null&&hbp!==null&&sf!==null&&ab+walks+hbp+sf>0?((hits+walks+hbp)/(ab+walks+hbp+sf)).toFixed(3).replace(/^0/,''):'—';const slg=ab>0&&hits!==null&&doubles!==null&&triples!==null&&hr!==null?((hits+doubles+2*triples+3*hr)/ab).toFixed(3).replace(/^0/,''):'—';const ops=obp!=='—'&&slg!=='—'?(Number(obp)+Number(slg)).toFixed(3).replace(/^0/,''):'—';return [['타율',avg],['홈런',fmt(hr)],['H',fmt(hits)],['타점',fmt(get('runsBattedIn','rbi','RBIs'))],['도루',fmt(get('stolenBases','steals'))],['실책',fmt(get('fieldingErrors')??0)],['출루율',obp],['장타율',slg],['출루율+장타율',ops]]}
function compactRecord(p,role){return baseballStatLine(p,role).map(([label,value])=>label+' '+value).join(' · ')}
function observerRow(p,label){return '<div class="observer-row" data-player="'+p.id+'" role="button" tabindex="0" aria-label="'+esc(p.name)+' 선수 상세 보기"><span class="observer-name">'+esc(p.name)+'</span><span class="observer-position">'+esc(label)+'</span><span class="observer-stats">'+esc(compactRecord(p,label))+'</span></div>'}
function lineupPanel(){const m=autoManager();const bullpenOrder=['필승조','롱릴리프','추격조','패전조','마무리'];const section=(title,players,role)=>'<section class="lineup-section observer-section"><h3>'+title+'</h3><div class="observer-table">'+players.map((p,i)=>'<div class="observer-line"><span class="observer-order">'+(i+1)+'</span>'+observerRow(p,role==='rotation'?'선발':positionName(p,playerBaseball(p)))+'</div>').join('')+'</div></section>';return '<div class="lineup-guide"><strong>감독 자동 편성 · 관찰 모드</strong><p>감독이 선발 능력순으로 1~5선발을 배치합니다. 타순은 선수별 타격·주루·장타 성향과 누적 시즌 성적을 함께 반영하며, 실제 경기에도 같은 타순이 적용됩니다. 구단주는 결과만 확인합니다.</p></div><div class="lineup-columns">'+section('감독 편성 타순 · 1~9번',m.lineup,'batting')+section('감독 선발 로테이션',m.rotation,'rotation')+ '<section class="lineup-section observer-section"><h3>불펜 투수진</h3><div class="observer-table">'+m.first.filter(p=>p.position==='P'&&!m.rotation.some(x=>x.id===p.id)).sort((a,b)=>bullpenOrder.indexOf(m.roles.get(a.id))-bullpenOrder.indexOf(m.roles.get(b.id))||m.score(b)-m.score(a)).map(p=>observerRow(p,m.roles.get(p.id)||'불펜')).join('')+'</div></section>'+'</div><p class="roster-empty">현재 타순과 선발진은 감독 AI가 시즌 성적·능력·피로도를 반영해 자동 결정하며 실제 경기에도 적용됩니다. 경기 전 상대 투수에 따라 일부 변경될 수 있습니다.</p>'}
