function pitcherRolesPanel(){const m=autoManager(),ps=m.first.filter(p=>p.position==='P');return '<div class="lineup-guide"><strong>투수진 자동 운용</strong><p>감독과 투수코치가 필승조·추격조·패전조·롱릴리프·마무리를 자동 배정합니다. 기록은 간소화된 경기 시뮬레이션을 기준으로 누적됩니다.</p></div><div class="entry-summary"><span>선발 <b>'+m.rotation.length+'</b></span><span>불펜 <b>'+ps.filter(p=>!m.rotation.includes(p)).length+'</b></span><span>마무리 <b>'+ps.filter(p=>m.roles.get(p.id)==='마무리').length+'</b></span></div><section class="entry-group observer-section"><div class="observer-table">'+ps.map(p=>observerRow(p,m.roles.get(p.id)||'불펜')).join('')+'</div></section>'}
function entryPanel(level){const m=autoManager(),team=state.players.filter(p=>p.teamId===state.teamId),first=team.filter(p=>m.chosenIds.has(p.id)),second=team.filter(p=>!m.chosenIds.has(p.id)&&p.level!=='육성'),farm=team.filter(p=>!m.chosenIds.has(p.id)&&p.level==='육성');const group=(title,ps)=>'<section class="entry-group observer-section"><h3>'+title+' <small>'+ps.length+'명</small></h3><div class="observer-table">'+ps.map(p=>observerRow(p,p.position==='P'?(m.roles.get(p.id)||'투수'):positionName(p,playerBaseball(p)))).join('')+'</div></section>';const summary='<div class="entry-summary"><span>1군 <b>'+first.length+'/28</b></span><span>2군 <b>'+second.length+'</b></span><span>육성 <b>'+farm.length+'</b></span></div>';return '<div class="lineup-guide"><strong>'+(level==='first'?'1군 선수단':'2군 · 육성 선수단')+'</strong><p>감독과 프런트가 선수단을 자동 편성하며 구단주는 명단과 성적만 확인합니다.</p></div>'+summary+(level==='first'?group('1군 선수단',first):group('2군 선수단',second)+group('육성 선수',farm))+'<p class="roster-empty">감독 AI가 경기 출전 선수단을 자동 선정합니다. 선수 명단의 등록 상태와는 구분됩니다.</p>'}
function showRosterPanel(mode){const target=document.querySelector('#roster-workspace');if(!target)return;document.querySelectorAll('[data-roster-mode]').forEach(x=>x.classList.toggle('active',x.dataset.rosterMode===mode));target.innerHTML=mode==='lineup'?lineupPanel():mode==='first'||mode==='second'?entryPanel(mode):rosterBody();bindRosterSearch()}
function bindRosterSearch(){const search=document.querySelector('#roster-search'),sort=document.querySelector('#roster-sort');if(search)search.oninput=e=>{rosterQuery=e.target.value;refreshRosterResults()};if(sort)sort.onchange=e=>{rosterSort=e.target.value;refreshRosterResults()};document.querySelectorAll('[data-player]').forEach(row=>{row.onclick=()=>showPlayer(Number(row.dataset.player));row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showPlayer(Number(row.dataset.player))}}})}
function roster(){return '<div class="roster-modes"><button class="active" data-roster-mode="list">선수 명단</button><button data-roster-mode="lineup">타순 · 선발진</button><button data-roster-mode="first">1군</button><button data-roster-mode="second">2군</button></div><div id="roster-workspace">'+rosterBody()+'</div>'}
function rosterBody(){const all=state.players.filter(p=>p.teamId===state.teamId&&!p.draftPending);const q=rosterQuery.trim().toLowerCase();const filtered=all.filter(p=>!q||p.name.toLowerCase().includes(q)||String(jerseyNumber(p)).includes(q)||positionName(p,playerBaseball(p)).includes(q));const sorter=(a,b)=>rosterSort==='age'?a.age-b.age||a.id-b.id:rosterSort==='salary'?b.salary-a.salary||a.id-b.id:jerseyNumber(a)-jerseyNumber(b)||a.id-b.id;const sections=[['1군 선수단',filtered.filter(p=>p.level==='1군')],['2군 선수단',filtered.filter(p=>p.level==='2군')],['육성 선수',filtered.filter(p=>p.level!=='1군'&&p.level!=='2군')]];return '<section class="dashboard-intro"><span class="section-kicker">TEAM ROSTER</span><h2>선수단 <span class="roster-total">'+all.length+'명</span></h2><p>등번호, 선수 이름 또는 포지션으로 검색할 수 있습니다.</p></section><div class="roster-toolbar"><input id="roster-search" type="search" placeholder="이름 · 등번호 · 포지션 검색" value="'+esc(rosterQuery)+'" autocomplete="off" aria-label="선수 검색"><select id="roster-sort" aria-label="선수 정렬"><option value="number"'+(rosterSort==='number'?' selected':'')+'>등번호순</option><option value="age"'+(rosterSort==='age'?' selected':'')+'>나이순</option><option value="salary"'+(rosterSort==='salary'?' selected':'')+'>연봉 높은순</option></select></div><div id="roster-results">'+rosterResults(sections,filtered.length)+'</div>'}
function rosterResults(sections,count){return '<div class="roster-count">검색 결과 '+count+'명</div>'+sections.map(([title,players])=>'<section class="dashboard-section roster-section"><div class="section-title"><div><h2>'+title+'</h2><p>'+players.length+'명</p></div></div><div class="roster-list">'+(players.length?players.sort((a,b)=>rosterSort==='age'?a.age-b.age||a.id-b.id:rosterSort==='salary'?b.salary-a.salary||a.id-b.id:Number(jerseyNumber(a))-Number(jerseyNumber(b))||a.id-b.id).map(p=>'<button class="roster-player player-row" data-player="'+p.id+'" aria-label="'+esc(p.name)+' 상세 보기"><span class="roster-avatar roster-number">'+esc(jerseyNumber(p))+'</span><span class="roster-person"><strong>'+esc(p.name)+'</strong><small>'+esc(positionName(p,playerBaseball(p)))+' · '+p.age+'세</small></span><span class="roster-extra">'+money(p.salary)+'</span><span class="roster-arrow">›</span></button>').join(''):'<p class="roster-empty">해당 선수가 없습니다.</p>')+'</div></section>').join('')}
function refreshRosterResults(){const all=state.players.filter(p=>p.teamId===state.teamId);const q=rosterQuery.trim().toLowerCase();const ps=all.filter(p=>!q||p.name.toLowerCase().includes(q)||String(jerseyNumber(p)).includes(q)||positionName(p,playerBaseball(p)).includes(q));const sections=[['1군 선수단',ps.filter(p=>p.level==='1군')],['2군 선수단',ps.filter(p=>p.level==='2군')],['육성 선수',ps.filter(p=>p.level!=='1군'&&p.level!=='2군')]];const target=document.querySelector('#roster-results');if(!target)return;target.innerHTML=rosterResults(sections,ps.length);target.querySelectorAll('[data-player]').forEach(row=>row.onclick=()=>showPlayer(Number(row.dataset.player)))}
const SKILL_LABELS={contact:'컨택',power:'장타력',eye:'선구안',speed:'주루',fielding:'수비',arm:'송구',control:'제구력',stuff:'구위',stamina:'체력'};
const TRAITS=['성실한 노력형','승부욕이 강한 유형','차분한 분석형','적극적인 도전형','팀워크 중심형','꾸준한 성장형'];
function ensureProfile(p){if(p.profile?.skills)return p.profile;const r=rng((p.id*2654435761)>>>0);const skills={};for(const k of Object.keys(SKILL_LABELS)){const relevant=p.position==='P'?['control','stuff','stamina'].includes(k):!['control','stuff','stamina'].includes(k);skills[k]=Math.max(20,Math.min(99,p.overall+(relevant?6:-8)+ri(r,-19,19)))}p.profile={skills,trait:TRAITS[ri(r,0,TRAITS.length-1)],contractYears:ri(r,1,5),injury:{status:'건강',days:0},growth:[]};return p.profile}
function skillOpinion(k,n){const label=SKILL_LABELS[k];const notes={contact:['정교한 타격에 어려움을 겪을 가능성이 있습니다.','타격 정확도는 평균적인 수준으로 평가됩니다.','공을 배트 중심에 맞히는 능력이 돋보입니다.'],power:['장타보다는 단타 위주의 타격이 예상됩니다.','상황에 따라 장타를 기대할 수 있습니다.','강한 타구를 생산하는 능력이 인상적입니다.'],eye:['유인구 대처와 볼넷 생산에 개선 여지가 있습니다.','볼을 고르는 판단은 무난한 편입니다.','스트라이크존 판단이 안정적이라는 평가입니다.'],speed:['주루에서 적극적인 기여는 제한적일 수 있습니다.','평균적인 주력을 갖췄습니다.','빠른 발을 활용한 주루가 강점입니다.'],fielding:['수비 범위와 안정성에 보완이 필요합니다.','수비에서 무난한 움직임을 보여줄 것으로 보입니다.','타구 판단과 수비 움직임이 좋다는 평가입니다.'],arm:['송구 능력이 약점으로 지적됩니다.','송구 능력은 무난한 편입니다.','강한 어깨가 강점입니다.'],control:['제구 기복이 우려됩니다.','스트라이크존 공략 능력은 무난합니다.','안정적인 제구가 강점으로 평가됩니다.'],stuff:['타자를 압도하는 구위는 부족한 편입니다.','구위는 평균적인 수준으로 보입니다.','타자의 배트를 밀어내는 구위가 돋보입니다.'],stamina:['긴 이닝 소화에는 부담이 예상됩니다.','체력 유지 능력은 무난한 편입니다.','긴 이닝을 소화할 체력을 갖춘 것으로 평가됩니다.']};return notes[k][n>=72?2:n>=50?1:0]}
function playerScouting(p){const x=ensureProfile(p),pitcher=p.position==='P',keys=pitcher?['stuff','control','stamina']:['contact','power','eye','speed','fielding'];const strong=keys.reduce((a,b)=>x.skills[a]>=x.skills[b]?a:b);const weak=keys.reduce((a,b)=>x.skills[a]<=x.skills[b]?a:b);const potential=p.potential>=82?'성장 여력이 크다는 의견이 있지만 실제 성장 여부는 지켜봐야 합니다.':p.potential>=65?'꾸준한 출전 경험에 따라 기량 향상을 기대할 수 있습니다.':'현재의 장점을 살리는 역할이 적합할 것으로 보입니다.';return '<p><strong>강점:</strong> '+esc(skillOpinion(strong,x.skills[strong]))+'</p><p><strong>보완점:</strong> '+esc(skillOpinion(weak,x.skills[weak]))+'</p><p><strong>향후 전망:</strong> '+esc(potential)+'</p>'}
const SCOUTS=[{name:'김도현',focus:'투구 내용과 제구',bias:{control:8,stuff:2,stamina:-3,contact:7,eye:8,power:-5}},{name:'박진우',focus:'구위와 결정구',bias:{stuff:9,control:-4,stamina:1,power:9,contact:-5}},{name:'이성호',focus:'이닝 소화와 안정성',bias:{stamina:8,control:6,stuff:-3,fielding:9,power:-6}}];
function scoutReport(p,s){const x=ensureProfile(p),pitcher=p.position==='P',b=playerBaseball(p),keys=pitcher?['stuff','control','stamina']:['contact','power','eye','speed','fielding'];const ranked=keys.map(k=>({key:k,score:x.skills[k]+(s.bias[k]||0)})).sort((a,b)=>b.score-a.score);const high=ranked[0],low=ranked[ranked.length-1];const focus=pitcher?s.focus:({김도현:'타격과 선구안',박진우:'장타력과 타구 질',이성호:'수비와 주루'}[s.name]||s.focus);const context=pitcher?'제구력·구위·체력·위기 대응 능력을 종합해 평가하며, 선발과 불펜 중 적합한 기용 방식은 감독이 결정합니다.':'타격 생산성과 수비 활용도를 함께 평가하고 있습니다.';return '<article class="scout-note"><h4>'+esc(s.name)+' 스카우트 <span class="muted">· 중점: '+esc(focus)+'</span></h4><p><strong>투수·야수 역할 평가:</strong> '+esc(context)+'</p><p><strong>강점:</strong> '+esc(skillOpinion(high.key,high.score))+'</p><p><strong>보완점:</strong> '+esc(skillOpinion(low.key,low.score))+'</p><p class="muted">실제 관찰 이력은 아직 없습니다. 내부 평가를 바탕으로 한 잠정 의견입니다.</p></article>'}
function performanceOpinion(p){if(p.position==='P'){if((p.inningsPitched||0)<20)return '투구 이닝이 충분하지 않아 실제 성적에 근거한 평가는 보류합니다.';const era=(p.earnedRuns||0)*9/p.inningsPitched;return era<3.5?'현재까지 실점 억제력이 좋은 편입니다.':era<5?'현재까지 평균적인 실점 관리 수준을 보였습니다.':'현재까지 실점 관리에 어려움을 겪었습니다.'}if((p.atBats||0)<60)return '타석 표본이 충분하지 않아 실제 성적에 근거한 평가는 보류합니다.';const avg=(p.hits||0)/p.atBats;return avg>=.3?'현재까지 안타 생산이 꾸준합니다.':avg>=.24?'현재까지 타격 성적은 무난한 편입니다.':'현재까지 안타 생산에 어려움을 겪었습니다.'}
function profileMarkup(p){const x=ensureProfile(p),b=playerBaseball(p);return '<section class="card"><h3>체력 및 출전 관리</h3><p>현재 상태: '+conditionText(p)+'</p><p>'+(p.position==='P'?'투구 이닝과 최근 등판 간격에 따라 피로가 누적되며, 감독이 회복 상태를 고려해 등판을 결정합니다.':'경기 출전량에 따라 피로가 쌓이고 휴식으로 회복됩니다.')+'</p><p class="muted">피로 누적과 회복은 경기 진행 시 반영됩니다.</p></section>'+'<section class="card"><h3>스카우트별 평가</h3><p class="muted">서로 다른 관점을 가진 구단 스카우트의 잠정 평가입니다. 능력치 숫자는 공개하지 않습니다.</p>'+SCOUTS.map(s=>scoutReport(p,s)).join('')+'</section><section class="card"><h3>실제 경기 성적에 따른 평가</h3><p>'+esc(performanceOpinion(p))+'</p><p class="muted">경기 결과가 기록되면 현재 누적 성적을 기준으로 의견이 달라집니다.</p></section><section class="card"><h3>성향 · 계약 · 몸 상태</h3><p>선수 성향: '+esc(x.trait)+'</p><p>계약 잔여 기간: '+x.contractYears+'년</p><p>부상 상태: '+esc(x.injury.status)+'</p></section><section class="card"><h3>성장 기록</h3>'+(x.growth.length?x.growth.map(g=>'<p>'+esc(g.season)+'시즌 · '+esc(g.note)+'</p>').join(''):'<p class="muted">아직 관찰된 성장 기록이 없습니다.</p>')+'</section>'}
function playerBaseball(p){const x=ensureProfile(p);if(!x.baseball){const r=rng((p.id*11939)>>>0);x.baseball={throwHand:r()<.72?'우투':'좌투',batHand:r()<.68?'우타':'좌타',delivery:p.position==='P'?['오버핸드','쓰리쿼터','사이드암','언더핸드'][Math.floor(r()*4)]:null,role:p.position==='P'?(r()<.48?'선발':'불펜'):null,fatigue:0,recovery:ri(r,8,17),lastAppearance:null}}return x.baseball}
function jerseyNumber(p){const roster=(state?.players||[]).filter(x=>x.teamId===p.teamId).sort((a,b)=>a.id-b.id);const assigned=new Map(),used=new Set();for(const x of roster){const n=x.jerseyNumber;if(Number.isInteger(n)&&n>=0&&n<=99&&!used.has(n)){assigned.set(x.id,n);used.add(n)}}for(const x of roster){if(assigned.has(x.id))continue;let n=1;while(used.has(n)&&n<=99)n++;if(n>99)return '—';assigned.set(x.id,n);used.add(n)}return assigned.get(p.id)??'—'}
function positionName(p,b){return p.position==='P'?'투수':({C:'포수','1B':'1루수','2B':'2루수','3B':'3루수',SS:'유격수',LF:'좌익수',CF:'중견수',RF:'우익수',IF:'내야수',OF:'외야수'}[p.position]||p.position)}
function playerFace(p){if(p.profile?.photoData&&/^data:image\/(jpeg|png|webp);base64,/.test(p.profile.photoData))return '<img class="real-player-photo" src="'+p.profile.photoData+'" alt="'+esc(p.name)+' 선수 프로필 사진">';const team=state.teams.find(t=>t.id===p.teamId);const initials=esc(team?.name||'BE');const num=String(jerseyNumber(p));return '<div class="official-player-art" role="img" aria-label="선수 사진 미등록 · 구단 유니폼 대체 이미지"><div class="jersey-halo"></div><div class="jersey-shoulders"><div class="jersey-body"><span class="jersey-letters">'+initials+'</span><span class="jersey-number">'+num+'</span></div></div><span class="jersey-photo-status">선수 사진 미등록</span></div>'}

function conditionText(p){const b=playerBaseball(p);return b.fatigue>=80?'휴식 필요':b.fatigue>=55?'피로 누적':b.fatigue>=30?'관리 필요':'정상'}
function careerSeasonRows(p){const stored=state.careerRecords?.[p.id]||[];const current=state.year||new Date().getFullYear();const years=[...stored];if(!years.some(x=>x.year===current)){const games=(state.gameResults||[]).filter(g=>[...(g.awayBatters||[]),...(g.homeBatters||[]),...(g.awayPitchers||[]),...(g.homePitchers||[])].some(x=>x.id===p.id));const first=games.length?seasonDate(games[0].day).getFullYear():current;years.push({year:current,teamId:p.teamId,games:p.games||0,atBats:p.atBats||0,hits:p.hits||0,homeRuns:p.homeRuns||0,runsBattedIn:p.runsBattedIn||0,runs:p.runs||0,stolenBases:p.stolenBases||0,inningsPitched:p.inningsPitched||0,earnedRuns:p.earnedRuns||0,pitchingWins:p.pitchingWins||0,pitchingLosses:p.pitchingLosses||0,saves:p.saves||0,holds:p.holds||0})}return years.sort((a,b)=>a.year-b.year)}
function careerTable(p){const pitcher=p.position==='P',rows=careerSeasonRows(p);const cols=pitcher?['연도','구단','등판','이닝','평균자책점','승','패','홀드','세이브']:['연도','구단','경기','타수','안타','타율','홈런','타점','도루'];const tableRows=rows.map(x=>{const team=state.teams.find(t=>t.id===x.teamId);const nums=pitcher?[x.games||0,Number(x.inningsPitched||0).toFixed(1),x.inningsPitched>0?((x.earnedRuns||0)*9/x.inningsPitched).toFixed(2):'—',x.pitchingWins||0,x.pitchingLosses||0,x.holds||0,x.saves||0]:[x.games||0,x.atBats||0,x.hits||0,x.atBats?((x.hits||0)/x.atBats).toFixed(3).replace(/^0/,''): '—',x.homeRuns||0,x.runsBattedIn||0,x.stolenBases||0];return '<tr><th>'+x.year+'</th><td>'+esc(team?.name||'이전 구단')+'</td>'+nums.map(n=>'<td>'+n+'</td>').join('')+'</tr>'}).join('');return '<h3 class="profile-heading">연도별 통산 기록</h3><p class="profile-note">실제 게임에서 저장된 시즌만 표시됩니다. 기록이 없는 과거 시즌은 생성하지 않습니다.</p><div class="scoreboard-scroll career-scroll"><table class="scoreboard-table career-stats"><thead><tr>'+cols.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+tableRows+'</tbody></table></div><p class="profile-note">데뷔부터 은퇴까지 시즌 종료 시 기록이 누적되는 선수 경력표입니다. 현재는 진행 중인 시즌 기록이 표시됩니다.</p>'}
function pitcherType(p){const a=pitchingArsenal(p),sk=ensureProfile(p).skills||{};const v=a.velocity;return v>=149?'강속구형':v>=144&&Number(sk.stuff||0)>=65?'파워피처형':Number(sk.control||0)>=Number(sk.stuff||0)+9?'제구형':a.pitches.length>=4?'변화구형':v<=137?'기교파형':'균형형'}
function pitcherPitchSpeed(p,name){const v=pitchingArsenal(p).velocity;const diff={'직구':0,'포심 패스트볼':0,'투심':-4,'커터':-5,'슬라이더':-10,'커브':-22,'체인지업':-14,'포크':-13,'스플리터':-12,'싱커':-5};return Math.max(95,v+(diff[name]??-12))}
function pitcherVisual(p){const a=pitchingArsenal(p),type=pitcherType(p),colors=['#dca85b','#62a8ff','#a58dff','#55d8ad','#ed7e84'];const rows=a.usage.map((x,i)=>'<div class="emp-pitch-row"><span>'+esc(x.name)+'</span><span>'+pitcherPitchSpeed(p,x.name)+'km/h</span><div class="emp-pitch-track"><i style="width:'+x.percent+'%;background:'+colors[i%colors.length]+'"></i></div><strong>'+x.percent+'%</strong></div>').join('');return '<section class="emp-scout-section"><h3>선수 유형</h3><div class="emp-type-card"><span class="emp-type-icon">⚾</span><div><strong>'+esc(type)+'</strong><p>투구폼 '+esc(playerBaseball(p).delivery)+' · 최고 구속 '+a.velocity+'km/h</p><p>구속과 구종은 선수의 능력 및 성장에 따라 달라집니다.</p></div></div></section><section class="emp-scout-section"><h3>주요 구종 ('+a.usage.length+'개)</h3>'+rows+'</section>'}
function pitcherChart(p){const a=pitchingArsenal(p),colors=['#3278c6','#16a085','#9166cc','#d58b36','#c34d70','#458a9c'],total=a.usage.reduce((n,x)=>n+x.percent,0)||100;return '<section class="pitch-chart-card"><div class="pitch-chart-heading"><span>구종 분석</span><strong>'+esc(pitcherType(p))+'</strong></div><p class="pitch-chart-caption">구종별 예상 구속과 구사율 · 최고 구속 '+a.velocity+'km/h</p><div class="pitch-chart-head"><span>구종</span><span>구속</span><span>구사율</span><span>비율</span></div>'+a.usage.map((x,i)=>{const pct=Math.round(x.percent/total*100);return '<div class="pitch-chart-line"><strong>'+esc(x.name)+'</strong><span>'+Math.min(a.velocity,pitcherPitchSpeed(p,x.name))+' km/h</span><div class="pitch-chart-track"><i style="width:'+pct+'%;background:'+colors[i%colors.length]+'"></i></div><b>'+pct+'%</b></div>'}).join('')+'<div class="pitch-bonus-panel"><h3>구속별 경기 효과</h3><strong>'+esc(pitcherSpeedBonus(p).name)+' · '+pitcherSpeedBonus(p).velocity+'km/h</strong><div>피안타 억제 효과 '+Math.round(pitcherSpeedBonus(p).hit*100)+'%</div><div>탈삼진 효과 '+Math.round(pitcherSpeedBonus(p).strikeout*100)+'%</div><p>제구·구위·피로도와 함께 경기 결과에 반영됩니다.</p></div></section>'}
function pitcherSpeedBonus(p){const v=pitchingArsenal(p).velocity;const t=v>=155?['최상급 강속구',.13,.18]:v>=150?['강속구',.09,.12]:v>=145?['빠른 공',.05,.07]:v>=140?['평균 이상',.02,.03]:v>=135?['평균 구속',0,0]:['저속형',-.03,-.03];return {name:t[0],hit:t[1],strikeout:t[2],velocity:v}}
function playerPhysical(p){const r=rng(((Number(p.id)||1)*19733+919)>>>0);const h=172+Math.floor(r()*22);return {height:h,weight:Math.max(65,Math.round((h-100)*.83+Math.floor(r()*18)-4))}}
function profileStatTable(stats){return '<div class="profile-stats-table">'+stats.map(x=>'<div class="profile-stat-item"><span>'+esc(x[0])+'</span><strong>'+esc(String(x[1]))+'</strong></div>').join('')+'</div>'}
function playerDetail(p){const t=state.teams.find(t=>t.id===p.teamId),b=playerBaseball(p),isP=p.position==='P',name=esc(p.name),club=esc(t.city+' '+t.name),bat=(b.throwHand==='좌투'?'좌투':'우투')+' · '+b.batHand;const number=jerseyNumber(p),posName=positionName(p,b),physical=playerPhysical(p);const basic=[['등번호','#'+number],['소속',club],['포지션',posName],['나이',p.age+'세'],['키',physical.height+'cm'],['몸무게',physical.weight+'kg'],['투타',bat],['선수 구분',p.level],['연봉',money(p.salary)],...(isP?[['투구폼',b.delivery],['최고 구속',pitchingArsenal(p).velocity+'km/h'],['투수 유형',pitcherType(p)]]:[])];const batting=[['경기',p.games||0],['타수',p.atBats||0],['타율',p.atBats?((p.hits||0)/p.atBats).toFixed(3).replace(/^0/,''):'—'],['홈런',p.homeRuns||0],['안타',p.hits||0],['득점',p.runs||0],['타점',statNumber(p,['runsBattedIn','rbi'])??'—'],['도루',statNumber(p,['stolenBases','steals'])??'—']];const ip=statNumber(p,['inningsPitched']),er=statNumber(p,['earnedRuns']),h=statNumber(p,['hitsAllowed']),bb=statNumber(p,['walksAllowed']);const pitching=[['등판',p.games||0],['투구 이닝',ip??0],['평균자책점',ip>0?((er||0)*9/ip).toFixed(2):'—'],['승',statNumber(p,['pitchingWins','pitcherWins','win'])??'—'],['패',statNumber(p,['pitchingLosses','pitcherLosses','loss'])??'—'],['이닝당 출루 허용',ip>0&&h!==null&&bb!==null?((h+bb)/ip).toFixed(2):'—'],['퀄리티스타트',statNumber(p,['qualityStarts','qs'])??'—']];const stats=isP?baseballStatLine(p,pitcherRole(p)).map(([k,v])=>[k,v]):baseballStatLine(p).map(([k,v])=>[k,v]);return '<div class="player-overlay" id="player-overlay"><section class="player-panel pro-profile" role="dialog" aria-modal="true" aria-labelledby="player-title" style="--team-color:'+esc(t.color)+'"><header class="profile-top"><div><div class="profile-eyebrow">BASEBALL EMPIRE / 선수 상세 정보</div><strong>'+club+'</strong></div><button class="secondary" id="close-player" aria-label="상세 닫기">✕ 닫기</button></header><div class="profile-banner"><div class="profile-art">'+playerFace(p)+'<span class="photo-label">선수 카드</span></div><div class="profile-identity"><span class="profile-chip">'+esc(p.level)+' · '+esc(posName)+'</span><div class="profile-number">NO. '+number+'</div><div class="profile-name" id="player-title">'+name+'</div><div class="profile-sub">'+club+' <span>·</span> '+esc(posName)+' <span>·</span> '+esc(bat)+'</div><p class="profile-summary">'+(isP?'투수로서 '+esc(b.delivery)+' 투구폼을 사용합니다. 선발·불펜 보직은 감독이 팀 상황과 선수 컨디션에 따라 결정합니다.':'타격과 수비를 함께 평가하는 야수입니다. 경기 기록과 스카우트 의견을 종합해 살펴볼 수 있습니다.')+'</p><div class="profile-status">● '+conditionText(p)+'</div><label class="player-photo-upload">📷 선수 사진 등록 · 변경<input id="player-photo-input" type="file" accept="image/jpeg,image/png,image/webp" aria-label="선수 사진 등록"></label></div></div><div class="profile-tabs" role="tablist"><button class="active" data-profile-tab="overview">프로필</button><button data-profile-tab="scout">스카우트 평가</button><button data-profile-tab="record">시즌 기록</button><button data-profile-tab="career">계약 · 성장</button></div><div class="profile-content"><div data-profile-pane="overview"><h3 class="profile-heading">선수 기본 정보</h3><div class="profile-facts">'+basic.map(x=>'<div><small>'+esc(x[0])+'</small><strong>'+esc(x[1])+'</strong></div>').join('')+'</div>'+(isP?pitcherChart(p):'')+'<h3 class="profile-heading">시즌 주요 기록</h3>'+profileStatTable(stats)+'<div class="profile-note">현재 기록은 실제 시뮬레이션 결과가 저장되면 반영됩니다. 시즌 개막 전에는 기록이 없습니다.</div></div><div data-profile-pane="scout" hidden><h3 class="profile-heading">구단 스카우트 보고서</h3>'+SCOUTS.map(s=>scoutReport(p,s)).join('')+'<div class="profile-note">관찰 이력에 기반한 보고서는 향후 스카우트 시스템에 연동됩니다. 현재는 평가 성향별 잠정 의견입니다.</div></div><div data-profile-pane="record" hidden><h3 class="profile-heading">'+(isP?'투수':'타자')+' 시즌 기록</h3>'+profileStatTable(stats)+'<h3 class="profile-heading">경기 성적 분석</h3><p>'+esc(performanceOpinion(p))+'</p><div class="profile-note">경기별 기록과 최근 경기 로그는 실제 경기 엔진 도입 후 표시됩니다.</div></div><div data-profile-pane="career" hidden><h3 class="profile-heading">계약 및 몸 상태</h3><div class="profile-facts"><div><small>연봉</small><strong>'+money(p.salary)+'</strong></div><div><small>계약 잔여 기간</small><strong>'+ensureProfile(p).contractYears+'년</strong></div><div><small>컨디션</small><strong>'+conditionText(p)+'</strong></div><div><small>부상</small><strong>'+esc(ensureProfile(p).injury.status)+'</strong></div></div><h3 class="profile-heading">성장 기록</h3><p class="profile-note">'+(ensureProfile(p).growth.length?ensureProfile(p).growth.map(g=>esc(g.season)+'시즌: '+esc(g.note)).join(' / '):'아직 기록된 성장 변화가 없습니다.')+'</p><h3 class="profile-heading">체력 관리</h3><p>'+esc(p.position==='P'?(b.role==='선발'?'선발 등판 후 충분한 휴식이 필요합니다.':'연속 등판과 투구 수에 따라 휴식이 필요합니다.'):'연속 출장과 수비 부담에 따라 휴식이 필요합니다.')+'</p></div></div></section></div>'}
function showPlayer(id){const p=state?.players.find(x=>x.id===id);if(!p)return;detailPlayerId=id;const isNew=!p.profile;ensureProfile(p);if(isNew)saveProfileQuietly();document.querySelector('#player-overlay')?.remove();document.body.insertAdjacentHTML('beforeend',playerDetail(p));document.querySelector('#close-player').onclick=closePlayer;const photoInput=document.querySelector('#player-photo-input');if(photoInput)photoInput.onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('JPG, PNG, WebP 사진만 등록할 수 있습니다.');return}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),w=320,h=420;canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#e7edf5';ctx.fillRect(0,0,w,h);const ratio=Math.max(w/bitmap.width,h/bitmap.height),sw=w/ratio,sh=h/ratio;ctx.drawImage(bitmap,(bitmap.width-sw)/2,(bitmap.height-sh)/2,sw,sh,0,0,w,h);bitmap.close();const data=canvas.toDataURL('image/jpeg',.75);if(data.length>230000)throw Error('사진 크기가 너무 큽니다');ensureProfile(p).photoData=data;await saveProfileQuietly();const active=document.querySelector('[data-profile-tab].active')?.dataset.profileTab;showPlayer(p.id);if(active&&active!=='profile')document.querySelector('[data-profile-tab="'+active+'"]')?.click()}catch(err){alert('사진 등록 실패: '+err.message)}};document.querySelectorAll('[data-profile-tab]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-profile-tab]').forEach(x=>x.classList.toggle('active',x===btn));document.querySelectorAll('[data-profile-pane]').forEach(x=>x.hidden=x.dataset.profilePane!==btn.dataset.profileTab)});document.querySelector('#player-overlay').onclick=e=>{if(e.target.id==='player-overlay')closePlayer()};document.addEventListener('keydown',playerEscape);document.querySelector('#close-player').focus()}
async function saveProfileQuietly(){try{const data=structuredClone(state);data.lastSaved=new Date().toISOString();const tx=db.transaction('saves','readwrite');tx.objectStore('saves').put(data,'main');await new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});state.lastSaved=data.lastSaved}catch(e){console.error('프로필 저장 실패',e);throw e}}
function playerEscape(e){if(e.key==='Escape')closePlayer()}
function closePlayer(){detailPlayerId=null;document.querySelector('#player-overlay')?.remove();document.removeEventListener('keydown',playerEscape)}

let leaguePane='standings';
const awardCategories=[
 ['정규시즌 MVP','all',p=>p.position==='P'?((p.pitchingWins||0)*12+(p.pitchingStrikeouts||0)*.7+(p.saves||0)*3-(p.earnedRuns||0)*1.5):((p.hits||0)*1.6+(p.homeRuns||0)*6+(p.runsBattedIn||0)*2+(p.walks||0)*.5)],
 ['신인왕','rookie',p=>p.position==='P'?((p.pitchingWins||0)*12+(p.pitchingStrikeouts||0)*.6):((p.hits||0)*1.4+(p.homeRuns||0)*6+(p.runsBattedIn||0)*1.5)],
 ['타율 1위','average',p=>(p.hits||0)/Math.max(1,p.atBats||0)],
 ['홈런 1위','batter',p=>p.homeRuns||0],
 ['타점 1위','batter',p=>p.runsBattedIn||0],
 ['안타 1위','batter',p=>p.hits||0],
 ['득점 1위','batter',p=>p.runs||0],
 ['출루율 1위','average',p=>((p.hits||0)+(p.walks||0))/Math.max(1,(p.atBats||0)+(p.walks||0))],
 ['장타율 1위','average',p=>((p.hits||0)+3*(p.homeRuns||0))/Math.max(1,p.atBats||0)],
 ['도루 1위','batter',p=>p.stolenBases||0],
 ['다승 1위','pitcher',p=>p.pitchingWins||p.pitcherWins||0],
 ['평균자책점 1위','era',p=>-9*(p.earnedRuns||0)/Math.max(1,p.inningsPitched||0)],
 ['탈삼진 1위','pitcher',p=>p.pitchingStrikeouts||p.strikeoutsPitched||0],
 ['세이브 1위','pitcher',p=>p.saves||0],
 ['홀드 1위','pitcher',p=>p.holds||0],
 ...['투수','포수','1루수','2루수','3루수','유격수','외야수','지명타자'].map(pos=>['골든글러브 · '+pos,'gold:'+pos,p=>p.position==='P'?((p.pitchingWins||0)*10+(p.pitchingStrikeouts||0)*.6-(p.earnedRuns||0)):((p.hits||0)*1.4+(p.homeRuns||0)*5+(p.runsBattedIn||0)*1.5)])
];
function awardCandidates(category){const [name,kind,score]=category;let ps=state.players.filter(p=>kind==='all'?true:kind==='rookie'?p.age<=23&&p.games<=100:kind.startsWith('gold:')?(kind==='gold:투수'?p.position==='P':kind==='gold:포수'?p.position==='C':kind==='gold:외야수'?['LF','CF','RF','OF'].includes(p.position):kind==='gold:지명타자'?p.position!=='P':p.position===({'1루수':'1B','2루수':'2B','3루수':'3B','유격수':'SS'}[kind.slice(5)])):kind==='pitcher'||kind==='era'?p.position==='P':p.position!=='P');if(kind==='average'){const max=Math.max(0,...ps.map(p=>p.atBats||0));ps=ps.filter(p=>(p.atBats||0)>=Math.max(1,max*.55))}if(kind==='era'){const max=Math.max(0,...ps.map(p=>p.inningsPitched||0));ps=ps.filter(p=>(p.inningsPitched||0)>=Math.max(1,max*.55))}return ps.filter(p=>p.games>0||p.atBats>0||p.inningsPitched>0).sort((a,b)=>score(b)-score(a)||a.id-b.id).slice(0,5)}
function awardValue(category,p){const v=category[2](p);return ['타율 1위','출루율 1위','장타율 1위'].includes(category[0])?v.toFixed(3):category[0]==='평균자책점 1위'?(-v).toFixed(2):String(Math.round(v*10)/10)}
function awardsFinished(){return state.teams.every(t=>(t.wins||0)+(t.losses||0)+(t.draws||0)>=144)}
function finalizeAwards(){if(!awardsFinished()||state.awards?.[state.year])return;state.awards=state.awards||{};state.awards[state.year]=awardCategories.map(c=>{const p=awardCandidates(c)[0];return p?{title:c[0],playerId:p.id,playerName:p.name,teamId:p.teamId,value:awardValue(c,p)}:null}).filter(Boolean);for(const a of state.awards[state.year])clubNotice('시즌 시상','리그 '+a.title+' 수상',a.playerName+' 선수가 '+a.title+'을 수상했습니다. 시즌 공식 기록 '+a.value+'.',[a.teamId],[a.playerId])}
let awardGroup='overall';
function awardPanel(){const completed=awardsFinished(),awards=state.awards?.[state.year]||[],groups=[['overall','종합 시상'],['batter','타자 부문'],['pitcher','투수 부문'],['gold','골든글러브']];const categories=awardCategories.filter(c=>awardGroup==='overall'?['정규시즌 MVP','신인왕'].includes(c[0]):awardGroup==='gold'?c[1].startsWith('gold:'):awardGroup==='pitcher'?['pitcher','era'].includes(c[1]):['batter','average'].includes(c[1]));return '<section class="dashboard-section"><h2>'+state.year+' 시즌 '+(completed?'공식 수상 결과':'MVP · 개인 타이틀 후보')+'</h2><p>'+(completed?'정규시즌 종료 · 공식 수상자 확정':'시즌 기록에 따라 후보 순위가 변동됩니다.')+'</p><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0">'+groups.map(g=>'<button type="button" data-award-group="'+g[0]+'" style="padding:11px 6px;border-radius:10px;font-weight:700;border:1px solid '+(awardGroup===g[0]?'#206ab5':'#dce4ef')+';background:'+(awardGroup===g[0]?'#e7f2ff':'#fff')+';color:#173b61">'+g[1]+'</button>').join('')+'</div>'+categories.map(c=>{const official=awards.find(a=>a.title===c[0]);const candidates=awardCandidates(c);return '<div style="margin:12px 0;padding:14px;border:1px solid #dce4ef;border-radius:14px"><h3>'+esc(c[0])+'</h3>'+(official?'<p><strong>🏆 수상자 '+esc(official.playerName)+'</strong> · '+esc(official.value)+'</p>':'')+(candidates.length?candidates.map((p,i)=>'<button data-award-player="'+p.id+'" style="display:flex;width:100%;justify-content:space-between;gap:8px;padding:9px 4px;background:transparent;border:0;border-bottom:1px solid #e5e9ef;text-align:left;color:inherit"><span>'+(i+1)+'위 · '+esc(p.name)+' <small>'+esc(state.teams[p.teamId].name)+'</small></span><strong>'+esc(awardValue(c,p))+'</strong></button>').join(''):'<p>아직 기록이 없습니다.</p>')+'</div>'}).join('')+'</section>'}
function league(){if(leaguePane==='awards')return '<div style="display:flex;gap:8px;margin:12px 0"><button data-league-pane="standings">리그 순위</button><button data-league-pane="awards">MVP · 개인 타이틀</button></div>'+awardPanel();const sorted=[...state.teams].sort((a,b)=>b.wins-a.wins||a.losses-b.losses);return '<div style="display:flex;gap:8px;margin:12px 0"><button data-league-pane="standings">리그 순위</button><button data-league-pane="awards">MVP · 개인 타이틀</button></div><section class="dashboard-intro"><span class="section-kicker">LEAGUE STANDINGS</span><h2>리그 순위</h2><p>10개 구단의 정규시즌 현황</p></section><section class="dashboard-section"><div class="league-table"><div class="league-row league-head"><span>순위</span><span>구단</span><span>승</span><span>패</span><span>무</span></div>'+sorted.map((t,i)=>'<button type="button" data-league-team="'+t.id+'" class="league-row '+(t.id===state.teamId?'my-team':'')+'"><span class="rank">'+(i+1)+'</span><span class="league-team">'+teamLogo(t)+''+esc(t.city+' '+t.name)+'</span><span>'+t.wins+'</span><span>'+t.losses+'</span><span>'+t.draws+'</span></button>').join('')+'</div></section><section class="dashboard-section"><span class="section-kicker">LEAGUE DEVELOPMENT</span><h2>리그 운영 안내</h2><p class="support-text">경기 일정·LIVE 관전·자동 운영 시스템은 다음 개발 단계에서 연결됩니다. 경기 결과와 선수 성적은 홈의 다음 경기일 진행 버튼으로 누적됩니다.</p></section>'}
function openLeagueTeam(id){const t=state.teams[id];if(!t)return;const ps=state.players.filter(p=>p.teamId===id).sort((a,b)=>a.position==='P'?-1:b.position==='P'?1:a.name.localeCompare(b.name,'ko'));document.querySelector('#league-team-overlay')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="game-news-overlay" id="league-team-overlay"><section class="game-news-dialog" role="dialog" aria-modal="true"><header><div><small>LEAGUE CLUB · 선수단</small><h2>'+esc(t.city+' '+t.name)+' · '+ps.length+'명</h2></div><button id="close-league-team">× 닫기</button></header><div class="league-roster-list">'+[['1군',ps.filter(p=>p.level==='1군')],['2군',ps.filter(p=>p.level==='2군')],['육성',ps.filter(p=>p.level!=='1군'&&p.level!=='2군')]].map(([name,group])=>'<h3>'+name+' · '+group.length+'명</h3>'+group.map(p=>'<button class="league-roster-player" data-player="'+p.id+'"><b>'+esc(p.name)+'</b><span>'+esc(p.position==='P'?'투수':p.position)+' · '+p.age+'세</span><span>›</span></button>').join('')).join('')+'</div></section></div>');document.querySelector('#close-league-team').onclick=()=>document.querySelector('#league-team-overlay')?.remove();document.querySelectorAll('#league-team-overlay [data-player]').forEach(x=>x.onclick=()=>showPlayer(Number(x.dataset.player)))}
function history(){const h=state.history;return '<section class="dashboard-intro"><span class="section-kicker">HALL OF HISTORY</span><h2>리그 역사</h2><p>창설 첫해부터 쌓이는 리그의 공식 기록</p></section><div class="history-grid">'+[['역대 우승',h.champions.length,'트로피'],['영구결번',h.retiredNumbers.length,'등번호'],['명예의 전당',h.hallOfFame.length,'헌액 선수']].map(x=>'<article class="history-tile"><span>'+x[2]+'</span><strong>'+x[1]+'</strong><small>'+x[0]+'</small></article>').join('')+'</div><section class="dashboard-section empty-history"><div class="history-emblem">★</div><h2>역사가 시작되는 시즌</h2><p>아직 공식 역사 기록이 없습니다.<br>첫 시즌의 기록이 이곳에 쌓입니다.</p></section>'}
function render(){if(state){ensureSeasonCalendar();restoreLegacyDrafts();}closePlayer();document.body.classList.toggle('be-start-screen',entryMode==='title');if(entryMode==='title'){titleScreen();return}if(!state){welcome();return}const t=state.teams[state.teamId];const views={home,roster,league,history};app.innerHTML='<main class="wrap game-shell"><header class="header game-header"><div class="header-brand"><span class="header-league">BASEBALL EMPIRE <span class="header-season">'+seasonDateLabel(displayedGameDay())+' · '+state.year+' SEASON'+'</span></span><h1>'+esc(t.city+' '+t.name)+'</h1></div><div class="header-actions"><span class="owner-label">OWNER</span><button class="secondary back-menu" id="back-to-title">← 메뉴</button></div></header>'+views[tab]()+'</main><nav class="nav">'+[['home','홈'],['roster','선수단'],['league','리그'],['history','역사']].map(([k,n])=>'<button class="'+(tab===k?'active':'')+'" data-tab="'+k+'"><span class="nav-icon">'+({home:'⌂',roster:'♟',league:'▥',history:'★'}[k])+'</span><span>'+n+'</span></button>').join('')+'</nav>';document.querySelector('#back-to-title').onclick=()=>{entryMode='title';render()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});if(tab==='league'){document.querySelectorAll('[data-award-group]').forEach(x=>x.onclick=()=>{awardGroup=x.dataset.awardGroup;render()});document.querySelectorAll('[data-league-pane]').forEach(x=>x.onclick=()=>{leaguePane=x.dataset.leaguePane;render()});document.querySelectorAll('[data-award-player]').forEach(x=>x.onclick=()=>showPlayer(Number(x.dataset.awardPlayer)));document.querySelectorAll('[data-league-team]').forEach(x=>x.onclick=()=>openLeagueTeam(Number(x.dataset.leagueTeam)))}if(tab==='roster'){bindRosterSearch();document.querySelectorAll('[data-roster-mode]').forEach(x=>x.onclick=()=>showRosterPanel(x.dataset.rosterMode))}if(tab==='home'){document.querySelectorAll('[data-club-notice]').forEach(x=>x.onclick=()=>openClubNotice(x.dataset.clubNotice.startsWith('roster:')?x.dataset.clubNotice:Number(x.dataset.clubNotice)));document.querySelectorAll('[data-game-day]').forEach(x=>x.onclick=()=>openGameArticle(Number(x.dataset.gameDay),Number(x.dataset.gameAway)));const days=[...new Set((state.gameResults||[]).map(g=>g.day))].sort((a,b)=>b-a),active=days.includes(window.beNewsDay)?window.beNewsDay:days[0];const switchDay=delta=>{const i=days.indexOf(active)+delta;if(i>=0&&i<days.length){window.beNewsDay=days[i];render()}};const prev=document.querySelector('#news-prev-day'),next=document.querySelector('#news-next-day');if(prev)prev.onclick=()=>switchDay(1);if(next)next.onclick=()=>switchDay(-1);document.querySelector('#advance-day').onclick=advanceSeason;document.querySelector('#save').onclick=()=>save().catch(e=>alert('저장 실패: '+e.message));document.querySelector('#backup').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='baseball-empire-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelector('#restore').onchange=async e=>{try{if(!e.target.files.length)return;const data=JSON.parse(await e.target.files[0].text());if(data.schema!==1||!Array.isArray(data.teams)||data.teams.length!==10||!Array.isArray(data.players)||!Number.isInteger(data.teamId)||data.teamId<0||data.teamId>9)throw Error('지원하지 않는 백업');if(!confirm('현재 저장 데이터를 백업 파일로 교체할까요?'))return;const old=state;state=data;try{await save()}catch(err){state=old;throw err}}catch(err){alert('복원 실패: '+err.message)}}}}
(async()=>{try{db=await openDB();state=await load();if(state&&state.schema!==1){app.innerHTML='<main class="wrap"><h2>지원되지 않는 저장 버전</h2><p>데이터 보호를 위해 자동 초기화하지 않았습니다.</p></main>';return}entryMode='title';render()}catch(e){app.innerHTML='<main class="wrap"><h2 class="error">저장소 초기화 실패</h2><p>'+esc(e.message)+'</p></main>'}})();